def fill_symmetric(grid, bg=6, axes=((1,1),(0,1),(1,0),(0,0))):
    """Fill every bg-colored cell from its symmetric counterparts (transpose and mirror
    about the axis between the two middle rows/columns, i.e. i <-> 31-i for a 30x30 grid),
    iterating until every bg cell has a unique candidate value."""
    n=len(grid); m=len(grid[0])
    g=[row[:] for row in grid]
    def cp(i,j):
        out=[]
        for fi,fj in axes:
            a= n+1-i if fi else i
            b= m+1-j if fj else j
            out.append((a,b))
        return out + ([(j,i)] if n==m else [])
    for _ in range(n*m):
        ch=False
        for i in range(n):
            for j in range(m):
                if g[i][j]==bg:
                    vals={g[a][b] for a,b in cp(i,j) if 0<=a<n and 0<=b<m and g[a][b]!=bg}
                    if len(vals)==1: g[i][j]=vals.pop(); ch=True
        if not ch: break
    return g
